function ogWrap(text, maxChars){
  var words=String(text||'').split(/\s+/).filter(Boolean);
  var lines=[], cur='';
  for(var i=0;i<words.length;i++){
    var w=words[i];
    while(w.length>maxChars){ if(cur){ lines.push(cur); cur=''; } lines.push(w.slice(0,maxChars)); w=w.slice(maxChars); }
    var t=cur?cur+' '+w:w;
    if(t.length>maxChars){ lines.push(cur); cur=w; } else { cur=t; }
  }
  if(cur) lines.push(cur);
  return lines;
}
function ogFontSize(title){
  var len=String(title||'').length;
  if(len<=12) return 96; if(len<=24) return 76; if(len<=40) return 60; return 48;
}
function ogColor(c){ var s=String(c||'').trim(); return /^#[0-9a-fA-F]{3}([0-9a-fA-F]{3})?$/.test(s) ? s : '#5E6AD2'; }
function ogEsc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function ogMeta(d){
  d=d||{};
  var t=ogEsc(d.title||''), s=ogEsc(d.subtitle||'');
  return ['<meta property="og:title" content="'+t+'">',
    '<meta property="og:description" content="'+s+'">',
    '<meta property="og:type" content="website">',
    '<meta property="og:image" content="og.png">',
    '<meta name="twitter:card" content="summary_large_image">',
    '<meta name="twitter:title" content="'+t+'">',
    '<meta name="twitter:description" content="'+s+'">'].join('\n');
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { ogWrap:ogWrap, ogFontSize:ogFontSize, ogColor:ogColor, ogEsc:ogEsc, ogMeta:ogMeta };
}
if (typeof window !== 'undefined') {
  window.OgForgePure = { ogWrap:ogWrap, ogFontSize:ogFontSize, ogColor:ogColor, ogEsc:ogEsc, ogMeta:ogMeta };
}
